public class Bar {
   private void foo()
   {
        int localVariable1;
        localVariable1 = 1;

        switch (localVariable1) {
            case 1:
                int a; // correct
                a = 1;
            case 2:
                int a; // correct
                a = 2;
                int b; // incorrect
            case 3: {
                int a; // correct
                a = 3;
                int b = 3; // incorrect
            }
            default:
                int a; // correct
                a = 4;
                int b; // incorrect
        }
   }
}

public class Bar {
   private String getPassword()
   {
      byte[] encoded = GlobalConfigMap.
         getInstance().
         getVault().
         secret("database.password").
         getValue();

      byte[] decoded = Base64.
         getDecoder().
         decode(encoded);

      return new String(decoded, StandardCharsets.UTF_8);
   }
}

public class Bar {
   private String getPassword()
   {
      byte[] decoded;
      byte[] encoded;

      encoded = GlobalConfigMap.
         getInstance().
         getVault().
         secret("database.password").
         getValue();

      decoded = Base64.
         getDecoder().
         decode(encoded);

      return new String(decoded, StandardCharsets.UTF_8);
   }
}

